import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { Tramite } from '../../../models/tramite';
import { TramiteService } from '../../../controllers/tramite.service';
import { InfoGeneralComponent } from './tabs/info-general/info-general.component';
import { DocumentosTramiteComponent } from './tabs/documentos-tramite.component/documentos-tramite.component';
import { TablaComponent } from '../../../shared/tabla/tabla.component';


@Component({
  selector: 'app-tramites-detalles',
  standalone: true,
  imports: [CommonModule, InfoGeneralComponent, RouterModule, DocumentosTramiteComponent, TablaComponent],
  templateUrl: './tramites-detalles.html',
  styleUrl: './tramites-detalles.css',
})
export class TramitesDetalles implements OnInit {
  tramite: Tramite | undefined;
  loading = true;
  activeTab = 'info-general';



  private tramiteService = inject(TramiteService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  ngOnInit(): void {
    this.route.params.subscribe((params) => {
      if (params['id']) {
        this.loadTramite(params['id']);
      }

    });
  }

  async loadTramite(id: number): Promise<void> {
    this.tramite = await this.tramiteService.find(id, {
      relations: ['*'],
      loader: true,
    });

    if (!this.tramite) {
      console.error('Trámite no encontrado');
    }

    this.loading = false;
  }

  setActiveTab(tab: string): void {
    this.activeTab = tab;
  }
  getStatusBadgeClass(status: string | undefined): string {
    if (!status) return 'bg-secondary';

    const statusClasses: Record<string, string> = {
      APROBADA: 'bg-success',
      INICIADA: 'bg-warning',
      RECIBIDA: 'bg-info',
      EN_REVISION: 'bg-info',
      VALIDADA: 'bg-success',
      RECHAZADA: 'bg-danger',
      CANCELADA: 'bg-dark',
    };

    return statusClasses[status] || 'bg-secondary';
  }
  getTabClasses(tabName: string): Record<string, boolean> {
    const activo = this.activeTab === tabName;

    return {
      'nav-link': true,
      'bg-primary': activo,
      'text-white': activo,
      'text-primary': !activo,
      'bg-transparent': !activo,
    };
  }
  volver(): void {
    this.router.navigateByUrl('/main/tramites');
  }
}